"use client";

import { useState } from "react";
import { Button, toast } from "@heroui/react";
import { FormModal } from "@/components/ui/form-modal";
import { TextInput } from "@/components/ui/form";
import { ItemElementView } from "@/components/admin/item-element";
import { api, ApiError, errorText, type KecermatanPreview } from "@/lib/api/client";
import { useAdminKecermatanBuilderT } from "@/lib/i18n/dict/admin-kecermatan-builder";

/** "Lihat contoh": one column generated by the server from the saved test and never stored. */
export function KecermatanPreviewModal({
  testId,
  kolomCount,
  isOpen,
  onOpenChange,
}: {
  testId: string;
  kolomCount: number;
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const t = useAdminKecermatanBuilderT();
  const [kolom, setKolom] = useState("1");
  const [preview, setPreview] = useState<KecermatanPreview | null>(null);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Reusing the shown seed lets staff compare kolom k with k + N/2; a shuffle draws a new one.
  const generate = async (reuseSeed: boolean) => {
    setPending(true);
    setError(null);
    try {
      setPreview(
        await api.kecermatan.preview(testId, {
          kolom: Number(kolom) || 1,
          ...(reuseSeed && preview ? { seed: preview.seed } : {}),
        }),
      );
    } catch (err) {
      const message = err instanceof ApiError ? (err.fields?.kolom ?? err.message) : errorText(err, t.preview.failed);
      setError(message);
      toast.danger(t.preview.failed, { description: message });
    } finally {
      setPending(false);
    }
  };

  return (
    <FormModal
      isOpen={isOpen}
      onOpenChange={(open) => {
        onOpenChange(open);
        if (!open) {
          setPreview(null);
          setError(null);
        }
      }}
      title={t.preview.title}
      description={t.preview.description}
      size="lg"
      footer={
        <>
          <Button variant="ghost" onPress={() => onOpenChange(false)}>
            {t.preview.close}
          </Button>
          {preview && (
            <Button variant="secondary" isDisabled={pending} onPress={() => void generate(false)}>
              {t.preview.again}
            </Button>
          )}
          <Button variant="primary" isDisabled={pending} onPress={() => void generate(true)}>
            {pending ? t.preview.generating : t.preview.show}
          </Button>
        </>
      }
    >
      <TextInput
        label={t.preview.kolomLabel(kolomCount)}
        type="number"
        min={1}
        max={kolomCount}
        value={kolom}
        onChange={(e) => setKolom(e.target.value)}
      />
      {error && (
        <p className="rounded-control border border-danger/30 bg-danger-soft px-3 py-2 text-caption text-danger-soft-foreground">{error}</p>
      )}
      {preview && (
        <div className="max-h-80 space-y-3 overflow-auto">
          <div className="rounded-tile border border-border bg-surface-secondary p-4">
            <p className="mb-3 text-caption font-medium text-muted">{t.preview.referenceHeading}</p>
            <div className="flex flex-wrap gap-2">
              {preview.reference.map((item) => (
                <ItemGroup key={item.label} label={item.label} elements={item.elements} />
              ))}
            </div>
          </div>
          {preview.soal.map((soal, at) => (
            <div key={at} className="rounded-tile bg-accent-soft p-4">
              <p className="mb-3 text-caption font-medium text-muted">
                {t.preview.soalHeading(at + 1)} · {t.preview.missingLabel(soal.missing)}
              </p>
              <div className="flex flex-wrap gap-2">
                {soal.shown.map((label) => {
                  const item = preview.reference.find((r) => r.label === label);
                  return item ? <ItemGroup key={label} label={label} elements={item.elements} /> : null;
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </FormModal>
  );
}

function ItemGroup({ label, elements }: { label: string; elements: KecermatanPreview["reference"][number]["elements"] }) {
  return (
    <div className="flex items-center gap-1.5 rounded-control border border-border bg-surface px-2.5 py-1.5">
      <span className="text-label font-semibold text-accent">{label}</span>
      {elements.map((el, i) => (
        <ItemElementView key={i} element={el} className="size-6 text-xl" />
      ))}
    </div>
  );
}
